-- Seed dữ liệu cho Blog, Voucher và Giải đấu.
-- Chạy sau database/seed_extra_reviews.sql trong Supabase SQL Editor.
--
-- ===== QUY ƯỚC ID =====
-- blog_categories (bc): bc0001 – bc0004
-- vouchers (v): v0001 – v0010
-- blog_posts (bp): bp0001 – bp0010
-- tournaments (tn): tn0001 – tn0010
-- ================================================

-- ── Blog categories (bc) ──────────────────────────────────────────────
on conflict (slug) do nothing;

-- ── Vouchers (v) ──────────────────────────────────────────────────────
on conflict (code) do nothing;

-- ── Blog posts (bp) ───────────────────────────────────────────────────
on conflict (slug) do nothing;

-- ── Tournaments (tn) ──────────────────────────────────────────────────
on conflict (slug) do nothing;

-- ── Cập nhật sequences ────────────────────────────────────────────────
select setval('seq_blog_categories', 4);
select setval('seq_vouchers', 10);
select setval('seq_blog_posts', 10);
select setval('seq_tournaments', 10);
