insert into blog_posts (id, author_id, title, slug, excerpt, content, cover_image_url, category_id, status, visibility, created_at, updated_at, published_at) values
('bp0001','u0021','5 bước chọn sân bóng phù hợp cho đội phong trào','5-buoc-chon-san-bong-phu-hop','Checklist nhanh giúp đội bóng chọn sân đúng vị trí, mặt sân và ngân sách.','Khi chọn sân bóng, đội nên ưu tiên vị trí thuận tiện, mặt sân êm, hệ thống đèn tốt và khu gửi xe rõ ràng. Nếu đặt giờ cao điểm, hãy kiểm tra lịch trống trước ít nhất một ngày để tránh hết sân.','https://images.unsplash.com/photo-1526232761682-d26e03ac148e?auto=format&fit=crop&w=1200&q=80','bc0003','PUBLISHED','PUBLIC','2026-06-01 09:00:00+07','2026-06-01 09:00:00+07','2026-06-01 09:30:00+07'),
('bp0002','u0022','Kỹ thuật giao cầu lông ổn định cho người mới','ky-thuat-giao-cau-long-on-dinh','Cách cầm vợt, điểm chạm cầu và nhịp thở khi giao cầu.','Người mới nên bắt đầu bằng giao cầu thấp, giữ cổ tay thả lỏng và tập điểm rơi ổn định. Mỗi buổi chỉ cần 10 phút luyện giao cầu là có thể cải thiện rõ trong trận đấu.','https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?auto=format&fit=crop&w=1200&q=80','bc0001','PUBLISHED','PUBLIC','2026-06-02 08:30:00+07','2026-06-02 08:30:00+07','2026-06-02 09:00:00+07'),
('bp0003','u0023','Ăn gì trước khi đá bóng buổi tối?','an-gi-truoc-khi-da-bong-buoi-toi','Gợi ý bữa nhẹ giúp đủ năng lượng mà không bị nặng bụng.','Trước trận 60 đến 90 phút, người chơi nên chọn chuối, bánh mì, sữa chua hoặc yến mạch nhẹ. Tránh đồ chiên nhiều dầu để hạn chế cảm giác ì khi vận động.','https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&w=1200&q=80','bc0002','PUBLISHED','PUBLIC','2026-06-03 10:00:00+07','2026-06-03 10:00:00+07','2026-06-03 10:20:00+07'),
('bp0004','u0024','Pickleball: Vì sao môn này đang bùng nổ?','pickleball-vi-sao-dang-bung-no','Pickleball dễ chơi, vui và phù hợp nhiều độ tuổi.','Pickleball kết hợp nhịp độ của tennis, phản xạ của bóng bàn và tính cộng đồng rất cao. Người mới có thể làm quen nhanh, còn người chơi lâu năm vẫn có nhiều chiến thuật để nâng cấp trình độ.','https://images.unsplash.com/photo-1622279457486-62dcc4a431d6?auto=format&fit=crop&w=1200&q=80','bc0004','PUBLISHED','PUBLIC','2026-06-04 11:00:00+07','2026-06-04 11:00:00+07','2026-06-04 11:25:00+07'),
('bp0005','u0026','Cách đặt sân giờ vàng mà vẫn tiết kiệm','cach-dat-san-gio-vang-tiet-kiem','Mẹo dùng voucher, đặt nhóm và chọn ngày phù hợp.','Giờ vàng thường đông và giá cao hơn, nhưng người chơi vẫn có thể tiết kiệm bằng cách đặt sớm, dùng voucher, chia chi phí theo đội và ưu tiên sân có chính sách giá rõ ràng.','https://images.unsplash.com/photo-1579952363873-27f3bade9f55?auto=format&fit=crop&w=1200&q=80','bc0003','PUBLISHED','PUBLIC','2026-06-05 09:45:00+07','2026-06-05 09:45:00+07','2026-06-05 10:00:00+07'),
('bp0006','u0027','3 bài tập khởi động trước khi chơi tennis','3-bai-tap-khoi-dong-truoc-khi-choi-tennis','Khởi động vai, hông và cổ chân để giảm chấn thương.','Tennis yêu cầu xoay người và di chuyển liên tục, vì vậy khởi động vai, hông và cổ chân là rất quan trọng. Hãy dành ít nhất 8 phút trước khi vào sân.','https://images.unsplash.com/photo-1554068865-24cecd4e34b8?auto=format&fit=crop&w=1200&q=80','bc0001','PUBLISHED','PUBLIC','2026-06-06 07:30:00+07','2026-06-06 07:30:00+07','2026-06-06 08:00:00+07'),
('bp0007','u0028','Tổ chức giải phong trào cần chuẩn bị gì?','to-chuc-giai-phong-trao-can-chuan-bi-gi','Danh sách việc cần làm cho chủ sân và đội tổ chức.','Một giải phong trào tốt cần lịch thi đấu rõ, quy định đăng ký đơn giản, trọng tài phù hợp và kênh cập nhật kết quả nhanh. Chủ sân nên chuẩn bị khu check-in và bảng thông tin ngay từ đầu.','https://images.unsplash.com/photo-1517649763962-0c623066013b?auto=format&fit=crop&w=1200&q=80','bc0004','PUBLISHED','PUBLIC','2026-06-07 14:00:00+07','2026-06-07 14:00:00+07','2026-06-07 14:30:00+07'),
('bp0008','u0029','Giữ thể lực khi chơi bóng rổ 5v5','giu-the-luc-khi-choi-bong-ro-5v5','Cách phân phối sức và phục hồi trong trận.','Bóng rổ 5v5 cần nhiều pha tăng tốc ngắn. Người chơi nên chia sức theo hiệp, uống nước đúng lúc và tập bổ trợ chân để giữ phong độ cuối trận.','https://images.unsplash.com/photo-1546519638-68e109498ffc?auto=format&fit=crop&w=1200&q=80','bc0002','PUBLISHED','PUBLIC','2026-06-08 16:00:00+07','2026-06-08 16:00:00+07','2026-06-08 16:10:00+07'),
('bp0009','u0030','Kinh nghiệm tìm đồng đội chơi cầu lông','kinh-nghiem-tim-dong-doi-choi-cau-long','Cách mô tả trình độ và khung giờ để tìm nhóm phù hợp.','Khi tìm đồng đội, hãy ghi rõ trình độ, khu vực, khung giờ và mục tiêu chơi vui hay luyện tập. Việc mô tả rõ giúp nhóm ghép trận nhanh và ít hủy lịch hơn.','https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?auto=format&fit=crop&w=1200&q=80','bc0004','PUBLISHED','PUBLIC','2026-06-09 08:00:00+07','2026-06-09 08:00:00+07','2026-06-09 08:20:00+07'),
('bp0010','u0031','Chủ sân nên dùng voucher như thế nào?','chu-san-nen-dung-voucher-nhu-the-nao','Gợi ý tạo voucher để kéo khách vào khung giờ thấp điểm.','Voucher hiệu quả nhất khi gắn với mục tiêu rõ: kéo khách khung giờ thấp điểm, khuyến khích người mới quay lại hoặc tăng đặt nhóm. Chủ sân nên giới hạn thời hạn và số lượt dùng để kiểm soát chi phí.','https://images.unsplash.com/photo-1526232761682-d26e03ac148e?auto=format&fit=crop&w=1200&q=80','bc0003','PUBLISHED','PUBLIC','2026-06-10 09:00:00+07','2026-06-10 09:00:00+07','2026-06-10 09:30:00+07')
